/**
 * A Config contains and saves configuration information for all aspects of the renderer.
 * Changes to a config can be saved in local storage to preserve user preferences,
 * and configuration settings can be saved and pre-selected based on various aspects of the
 * user's device, such as wether it's a mobile device or not.
 *
 * Configs detect changes via use of the Proxy API to trap set events, which can be slow when
 * used frequently. As such, it's a good idea to only store properties in a config that you
 * anticipate being changed infrequently. Getting the properties frequently should have no penalty.
 */

// Note that this file has a lot more @ts-expect-error comments than usual. This is because we're
// using JS objects in a somewhat unorthodox (but legal) way that TypeScript really doesn't like.
// If I can find a way in the future to be more typesafe I'll take it, but in the meantime this
// is all *Jedi mindtrick handwave* just fine.

const UPDATED_CONFIGS = new Set<Config>();
// How frequently update configs will be cached out to storage.
const CONFIG_UPDATE_INTERVAL = 10 * 1000;

// Proxy handler for config objects to ensure that changing any attribute fires
// the appropriate events and marks the config to be saved
const CONFIG_HANDLER = {
  set(obj: Config, key: string, value: any) {
    // @ts-expect-error
    const changed = obj[key] !== value;
    // @ts-expect-error
    const ret = Reflect.set(...arguments);
    if (changed) {
      obj.fireChangedEvent(key, value);
    }
    return ret;
  },
  get: function (obj: Config, key: string) {
    const result = Reflect.get(obj, key)
    if(typeof result === 'function')
        return result.bind(obj)
    return result
  }
}

const configStringify = (key: string, value: any) => {
  return value instanceof Object && !(value instanceof Array) ?
    Object.keys(value).reduce((out, key) => {
      if (key != 'configRevision') {
        // @ts-expect-error
        out[key] = value[key];
      }
      return out;
    }, {}) : value;
}

function SaveAllConfigs() {
  if (UPDATED_CONFIGS.size) {
    for (const config of UPDATED_CONFIGS) {
      config.saveToStorage();
    }
    UPDATED_CONFIGS.clear();
  }
}

export interface ConfigEventDetail {
  property: string,
  value: any
}

