const CONFIG_DEFAULTS: Map<string, any> = new Map();

let updateInterval: number;

export class Config extends EventTarget {
  #loading = false;
  #nextRevision = 1;
  #revision = this.#nextRevision++;
  #configRevisions = new Map<string, number>();

  constructor() {
    super();
  }

  static Create<ConfigType extends Config>(configType: new() => ConfigType, args: any = null): ConfigType {
    const config = new configType();
    config.#loading = true;

    let defaults = CONFIG_DEFAULTS.get(config.configStorageName!);
    if (!defaults) {
      defaults = new configType();
      if (Object.hasOwn(config.constructor, 'SetDefaults')) {
        const deviceDefaults = (config.constructor as any).SetDefaults(isMobileBrowser(), args);
        defaults.#setConfigProperties(deviceDefaults);
      }
      CONFIG_DEFAULTS.set(config.configStorageName!, defaults);
    }

    config.#setConfigProperties(defaults);

    if (config.configStorageName) {
      config.loadFromStorage();
      config.updateFromQueryArgs();
    }
    if (!updateInterval) {
      updateInterval = setInterval(SaveAllConfigs, CONFIG_UPDATE_INTERVAL);
    }
    config.#loading = false;
    return new Proxy(config, CONFIG_HANDLER) as ConfigType;
  }

  get configStorageName(): string | null {
    return this.constructor.name;
  }

  fireChangedEvent(property: string, value: any) {
    if (this.#loading) { return; } // Don't fire a bunch of events while the config is loading.

    this.#updateRevision();

    if (this.configStorageName) {
      UPDATED_CONFIGS.add(this);
    }
    let event = new CustomEvent<ConfigEventDetail>('changed', {
      cancelable: false,
      bubbles: true,
      detail: {
        property,
        value,
      }
    });
    this.dispatchEvent(event);
  }

  #updateRevision() {
    // Get a revision number that is unique to this combination of config values
    const key = JSON.stringify(this, configStringify);
    const cachedRevision = this.#configRevisions.get(key);
    if (cachedRevision) {
      this.#revision = cachedRevision;
    } else {
      this.#revision = this.#nextRevision++;
      this.#configRevisions.set(key, this.#revision);
    }
  }

  get configRevision() { return this.#revision; }

  #getConfigProperties(): any {
    let defaults = CONFIG_DEFAULTS.get(this.configStorageName!);

    // Filter out only properties defined on this config object.
    return Object.keys(defaults).reduce((out, key) => {
      // Don't bother exporting values that match the defaults.
      // @ts-expect-error
      if (!defaults || defaults[key] !== this[key]) {
        // @ts-expect-error
        out[key] = this[key];
      }
      return out;
    }, {});
  }

  #setConfigProperties(obj: any) {
    if (!obj) { return; }
    for (const key of Object.keys(obj)) {
      if (Object.hasOwn(this, key)) {
        // @ts-expect-error
        if (this[key] == key) { continue; }
        // @ts-expect-error
        this[key] = obj[key];
        this.fireChangedEvent(key, obj[key]);
      } else {
        console.warn(`Attempting to set unknown config property: ${key}.`);
      }
    }
  }

  saveToStorage() {
    let storageName = this.configStorageName;
    if (!storageName) { throw new Error('Config does not specify a storage name'); }

    console.info(`Saving updates to Config: ${storageName}, revision ${this.configRevision}`);
    localStorage.setItem(storageName, JSON.stringify(this.#getConfigProperties()));
  }

  loadFromStorage() {
    let storageName = this.configStorageName;
    if (!storageName) { throw new Error('Config does not specify a storage name'); }

    let json = localStorage.getItem(storageName);
    if (!json) { return; }

    let obj: any;
    try {
      obj = JSON.parse(json);
    } catch(err: any) {
      console.warn(`Config loaded from localStorage was not valid json. ${err.message}`);
      return;
    }

    this.#setConfigProperties(obj);
  }

  async loadFromUrl(url: string) {
    const response = await fetch(url);
    let obj: any;
    try {
      obj = await response.json();
    } catch(err: any) {
      console.warn(`Config loaded from ${url} was not valid json. ${err.message}`);
      return;
    }

    this.#setConfigProperties(obj);
  }

  // Updates the config to use values given in the URL query args if they match
  updateFromQueryArgs() {
    const searchParams = new URLSearchParams(window.location.search);
    searchParams.forEach((value: string, key: string) => {
      if (Object.hasOwn(this, key)) {
        let parsedValue: any = undefined;
        // @ts-expect-error
        if (typeof this[key] === 'string') {
          parsedValue = value;
        // @ts-expect-error
        } else if (typeof this[key] === 'number') {
          parsedValue = parseFloat(value);
        // @ts-expect-error
        } else if (typeof this[key] === 'boolean') {
          parsedValue = parseInt(value, 10) != 0;
        }

        // @ts-expect-error
        if (parsedValue !== undefined && this[key] != parsedValue) {
          // @ts-expect-error
          this[key] = parsedValue;
          this.fireChangedEvent(key, parsedValue);
        }
      }
    });
  }

  resetToDefaults() {
    let storageName = this.configStorageName;
    if (!storageName) { throw new Error('Config does not specify a storage name'); }
    this.#setConfigProperties(CONFIG_DEFAULTS.get(storageName));
  }

  watch(...properties: string[]): ConfigWatcher {
    return new ConfigWatcher(this, ...properties);
  }
}


interface ConfigKeyValuePairs {
  [id: string]: any
}

/**
 * A ConfigWatcher is read-only Config that monitors a given subset of the properties of one or more
 * base Configs. This filters the configRevision property and 'change' events to only respond to the
 * given properties, which in turn makes it less noisy when updating dependent values.
 *
 * Typically a ConfigWatcher is created from the base Config with the watch() method:
 *
 * ```js
 *  class SampleConfig extends Config {
 *    foo = 10;
 *    bar = 'test';
 *    baz = false;
 *  }
 *  const config = Config.Create(SampleConfig);
 *
 *  const watched = config.watch('foo', 'baz');
 *  console.log(watched.foo); // 10
 *  config.foo = 12;
 *  console.log(watched.foo); // 12
 * ```
 */
export class ConfigWatcher extends Config implements ConfigKeyValuePairs {
  constructor(config?: Config, ...properties: string[]) {
    super();
    if (config) {
      this.addWatch(config, ...properties);
    }
  }

  get configStorageName(): string | null {
    return null;
  }

  addWatch(config: Config, ...properties: string[]) {
    for (const property of properties) {
      if (Object.hasOwn(this, property)) {
        throw new Error(`ConfigWatcher is already watching a property named ${property}`);
      }
      // @ts-expect-error
      this[property] = config[property];
    }

    config.addEventListener('changed', (event: Event) => {
      const detail = (event as CustomEvent<ConfigEventDetail>).detail;
      if (Object.hasOwn(this, detail.property)) {
        // @ts-expect-error
        this[detail.property] = detail.value;
        this.fireChangedEvent(detail.property, detail.value);
      }
    });
  }
}
